"""Array-based d-ary min-heap with sift routines written once for arbitrary d.

Children of node i live at indices d*i+1 .. d*i+d; parent is (i-1)//d.
Larger d => shallower tree: cheaper pushes, but each pop must scan d children.
"""


class DHeap:
    def __init__(self, d=2, iterable=()):
        if d < 2:
            raise ValueError("d must be >= 2")
        self.d = d
        self._a = list(iterable)
        for i in range((len(self._a) - 2) // d, -1, -1):
            self._sift_down(i)

    def __len__(self):
        return len(self._a)

    def peek(self):
        if not self._a:
            raise IndexError("peek from empty heap")
        return self._a[0]

    def push(self, item):
        a = self._a
        a.append(item)
        self._sift_up(len(a) - 1)

    def pop(self):
        a = self._a
        if not a:
            raise IndexError("pop from empty heap")
        smallest = a[0]
        last = a.pop()
        if a:
            a[0] = last
            self._sift_down(0)
        return smallest

    # -- internals ---------------------------------------------------------

    def _sift_up(self, i):
        """Bubble node i up while it is smaller than its parent."""
        a = self._a
        d = self.d
        item = a[i]
        while i > 0:
            p = (i - 1) // d
            if a[p] <= item:
                break
            a[i] = a[p]
            i = p
        a[i] = item

    def _sift_down(self, i):
        """Bubble node i down to the smaller of its d children."""
        a = self._a
        n = len(a)
        d = self.d
        item = a[i]
        while True:
            first = d * i + 1
            if first >= n:
                break
            best = first
            last = min(first + d, n)
            for c in range(first + 1, last):
                if a[c] < a[best]:
                    best = c
            if a[best] >= item:
                break
            a[i] = a[best]
            i = best
        a[i] = item

    @staticmethod
    def heapsort(data, d=2):
        h = DHeap(d, data)
        out = []
        pop = h.pop
        while len(h):
            out.append(pop())
        return out

